// Prisma schema block as a comment string (datasource sqlite, two models — Technician with id and name, WorkOrder with id, title, notes, status with default intake, and a required relation to Technician with onDelete Restrict)
// export type PrismaClient = import('@prisma/client').PrismaClient

import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

export type Technician = {
  id: number
  name: string
}

export type WorkOrder = {
  id: number
  title: string
  notes: string
  status: 'intake' | 'diagnosed' | 'repaired' | 'delivered'
  technician_id: number
}

export const listOpenOrders = async () => {
  const orders = await prisma.workOrder.findMany({
    where: {
      status: 'intake',
    },
  })

  return orders
}

export const createOrder = async (
  title: string,
  notes: string,
  technician_id: number
) => {
  const order = await prisma.workOrder.create({
    data: {
      title,
      notes,
      status: 'intake',
      technician_id,
    },
  })

  return order
}

export const assignStatus = async (
  order_id: number,
  status: 'intake' | 'diagnosed' | 'repaired' | 'delivered'
) => {
  const order = await prisma.workOrder.update({
    where: {
      id: order_id,
    },
    data: {
      status,
    },
  })

  return order
}
